def get_user_input():
    """Get user input for operation and numbers."""
    while True:
        operation = input("Choose an operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            break
        else:
            print("Invalid operation. Please try again.")

    numbers = input("Enter two numbers separated by a space: ").strip().split()
    try:
        num1, num2 = float(numbers[0]), float(numbers[1])
    except ValueError:
        print("Invalid input. Please enter numbers only.")
        return get_user_input()

    return operation, num1, num2


def perform_operation(operation, num1, num2):
    """Perform the chosen operation on the two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation.")

    return result


def main():
    operation, num1, num2 = get_user_input()
    try:
        result = perform_operation(operation, num1, num2)
        print(f"The result of the operation is: {result}")
    except ValueError as e:
        print(e)


if __name__ == "__main__":
    main()
```

This program will ask the user to choose an operation and input two numbers. It will then perform the chosen operation on the two numbers and display the result. If the user enters invalid input or an invalid operation, the program will prompt the user to try again.
